// npm i express express-session
const session = require('express-session');
app.use(session({
  name: '__Host-sid',            // 防子域覆盖
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,     // 未登录不发会话
  cookie: { httpOnly: true, secure: true, sameSite: 'lax', path: '/' }
}));

app.post('/login', async (req, res, next) => {
  const user = await verifyPassword(req.body.username, req.body.password);
  if (!user) return res.status(401).send('用户名或密码错误');
  // 关键：认证成功后换新的会话 ID
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    req.session.save((err) => (err ? next(err) : res.redirect('/')));
  });
});

-- 一致性的一部分交给约束：余额不能为负
CREATE TABLE accounts (
  id      int PRIMARY KEY,
  balance numeric(12,2) NOT NULL CHECK (balance >= 0)
);
INSERT INTO accounts VALUES (1, 100), (2, 0);

-- 原子性：两条更新作为整体
BEGIN;
UPDATE accounts SET balance = balance - 150 WHERE id = 1;  -- 违反 CHECK，报错
UPDATE accounts SET balance = balance + 150 WHERE id = 2;
COMMIT;  -- PostgreSQL 中事务已处于失败状态，COMMIT 实际执行回滚

-- 保存点：只撤销事务中的一部分
BEGIN;
UPDATE accounts SET balance = balance - 30 WHERE id = 1;
SAVEPOINT before_bonus;
UPDATE accounts SET balance = balance + 999 WHERE id = 2;
ROLLBACK TO SAVEPOINT before_bonus;  -- 撤销加 999
UPDATE accounts SET balance = balance + 30 WHERE id = 2;
COMMIT;

SELECT * FROM accounts;  -- 1: 70, 2: 30

-- 规则：至少要有一名医生值班
CREATE TABLE doctors (name text PRIMARY KEY, on_call boolean);
INSERT INTO doctors VALUES ('alice', true), ('bob', true);

-- 会话 A                                  -- 会话 B
BEGIN ISOLATION LEVEL REPEATABLE READ;     -- BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM doctors               -- SELECT count(*) FROM doctors
  WHERE on_call;  -- 2                     --   WHERE on_call;  -- 2
UPDATE doctors SET on_call = false         -- UPDATE doctors SET on_call = false
  WHERE name = 'alice';                    --   WHERE name = 'bob';
COMMIT;                                    -- COMMIT;
-- 结果：两人都不值班，规则被破坏（写偏斜）

-- 改为 SERIALIZABLE 后，后提交的一方会失败：
-- ERROR: could not serialize access due to read/write dependencies
-- SQLSTATE 40001 → 应用捕获后重试整个事务
SHOW default_transaction_isolation;  -- PostgreSQL 默认 read committed

-- 复现（两个会话交替执行）
-- 会话 A: BEGIN; UPDATE accounts SET balance = balance - 10 WHERE id = 1;
-- 会话 B: BEGIN; UPDATE accounts SET balance = balance - 10 WHERE id = 2;
-- 会话 A: UPDATE accounts SET balance = balance + 10 WHERE id = 2;  -- 等待 B
-- 会话 B: UPDATE accounts SET balance = balance + 10 WHERE id = 1;  -- 形成环
-- ERROR: deadlock detected (SQLSTATE 40P01)

-- 修复：无论转账方向，都按 id 升序一次性锁住相关行
BEGIN;
SELECT id FROM accounts
WHERE id IN (1, 2)
ORDER BY id
FOR UPDATE;
UPDATE accounts SET balance = balance - 10 WHERE id = 2;
UPDATE accounts SET balance = balance + 10 WHERE id = 1;
COMMIT;

-- PostgreSQL：记录长时间锁等待，便于排查
ALTER SYSTEM SET log_lock_waits = on;
SELECT pg_reload_conf();
