-- 场景一：扣库存，锁住商品行后再判断
BEGIN;
SET LOCAL lock_timeout = '3s';          -- 等锁最多 3 秒（PostgreSQL）
SELECT stock FROM products WHERE id = 42 FOR UPDATE;
-- 应用判断 stock >= 1 后：
UPDATE products SET stock = stock - 1 WHERE id = 42;
INSERT INTO orders (product_id, qty) VALUES (42, 1);
COMMIT;

-- 场景二：多个 worker 并发领取任务，互不阻塞
BEGIN;
SELECT id, payload FROM jobs
WHERE status = 'pending'
ORDER BY id
LIMIT 1
FOR UPDATE SKIP LOCKED;
-- 拿到 id 后：
UPDATE jobs SET status = 'running', started_at = now() WHERE id = $1;
COMMIT;

-- 在帖子表冗余评论数，列表页不再 COUNT(*)
ALTER TABLE posts ADD COLUMN comment_count int NOT NULL DEFAULT 0;

CREATE FUNCTION sync_comment_count() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE posts SET comment_count = comment_count + 1 WHERE id = NEW.post_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE posts SET comment_count = comment_count - 1 WHERE id = OLD.post_id;
  END IF;
  RETURN NULL;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER comments_count_trg
AFTER INSERT OR DELETE ON comments
FOR EACH ROW EXECUTE FUNCTION sync_comment_count();

-- 定期对账：找出冗余值与真实值不一致的帖子
SELECT p.id, p.comment_count, count(c.id) AS actual
FROM posts p LEFT JOIN comments c ON c.post_id = p.id
GROUP BY p.id
HAVING p.comment_count <> count(c.id);

CREATE TABLE users (id bigint PRIMARY KEY, email text UNIQUE NOT NULL);

-- 组成关系：用户删了，其会话没有意义 → 级联删除
CREATE TABLE sessions (
  id      uuid PRIMARY KEY,
  user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE
);

-- 关联关系：订单要留存做账 → 拒绝删除有订单的用户
CREATE TABLE orders (
  id      bigint PRIMARY KEY,
  user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT
);

-- 可选关系：指派人离开，任务保留 → 置空
CREATE TABLE tasks (
  id          bigint PRIMARY KEY,
  assignee_id bigint REFERENCES users(id) ON DELETE SET NULL
);

-- PostgreSQL 不会自动为外键列建索引，级联与 JOIN 都依赖它
CREATE INDEX ON sessions (user_id);
CREATE INDEX ON orders (user_id);
CREATE INDEX ON tasks (assignee_id);
